import{_ as t,a,c as s,ac as n}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"第四册：流利英语 · 单元 3 语法总结","description":"L17–L24 规则、例句、易错点。","frontmatter":{"title":"第四册：流利英语 · 单元 3 语法总结","description":"L17–L24 规则、例句、易错点。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","summary":"L17–L24 规则、例句、易错点。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · 单元 3：证据、解释与表达焦点","link":"/life/english/new-concept/book-4/unit-03/overview"},"next":{"text":"第四册：流利英语 · 单元 3 单词与短语","link":"/life/english/new-concept/book-4/unit-03/vocabulary"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · 单元 3：证据、解释与表达焦点","link":"/life/english/new-concept/book-4/unit-03/overview"},"next":{"text":"第四册：流利英语 · 单元 3 单词与短语","link":"/life/english/new-concept/book-4/unit-03/vocabulary"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-03/grammar.md","filePath":"life/english/new-concept/book-4/unit-03/grammar.md"}'),i={name:"life/english/new-concept/book-4/unit-03/grammar.md"};function o(r,e,l,h,c,p){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="第四册-流利英语-·-单元-3-语法总结" tabindex="-1">第四册：流利英语 · 单元 3 语法总结 <a class="header-anchor" href="#第四册-流利英语-·-单元-3-语法总结" aria-label="Permalink to &quot;第四册：流利英语 · 单元 3 语法总结&quot;">​</a></h1><p><a href="/life/english/new-concept/book-4/unit-03/overview">单元导读</a> · <a href="/life/english/new-concept/book-4/unit-03/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-4/unit-03/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-4/unit-03/review">单元复习与自测</a></p><h2 id="cause、lead-to-与-be-associated-with" tabindex="-1">cause、lead to 与 be associated with <a class="header-anchor" href="#cause、lead-to-与-be-associated-with" aria-label="Permalink to &quot;cause、lead to 与 be associated with&quot;">​</a></h2><p>cause + 宾语表示造成结果，lead to 后接名词或动名词表示导致；be associated with 只表示存在关联，证据强度不同。A change was associated with fewer rabbits 与 A change caused the decline 不是同义改写。lead to 中的 to 是介词，因此接 doing 而非动词原形。生态叙述还应检查气候、食物和调查方法等变量，不能因为作者使用 cause 就认为因果已经得到充分证明。</p><p><strong>L17 原创例句：</strong> In the fictional survey, a wetter spring was associated with fewer rabbits near the field.</p><p>在这项虚构调查中，更潮湿的春季与田地附近较少的兔子相关。</p><p><strong>易错：</strong> 不要把 associated with 在摘要中升级为 caused；这改变了证据含义。</p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-017">Lesson 17</a></p><h2 id="感官动词的主动与被动转换" tabindex="-1">感官动词的主动与被动转换 <a class="header-anchor" href="#感官动词的主动与被动转换" aria-label="Permalink to &quot;感官动词的主动与被动转换&quot;">​</a></h2><p>see/watch/observe + 宾语 + 动词原形强调观察到一个完整动作，接现在分词强调动作正在进行。主动句中的不带 to 不定式在常见被动结构中恢复 to，例如 They saw it surface → It was seen to surface。若原来是 surfacing，被动仍可用 was seen surfacing。观察到动作不等于知道动物的目的，因此 should 或 wanted 等意图表达需要额外证据。</p><p><strong>L18 原创例句：</strong> The animal was seen to surface beside the boat twice.</p><p>有人看到那只动物在船边浮出水面两次。</p><p><strong>易错：</strong> The animal was seen surface 缺少 to；主动 We saw it surface 才使用不带 to 结构。</p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-018">Lesson 18</a></p><h2 id="同位语从句与定语从句" tabindex="-1">同位语从句与定语从句 <a class="header-anchor" href="#同位语从句与定语从句" aria-label="Permalink to &quot;同位语从句与定语从句&quot;">​</a></h2><p>the idea that… 中 that 从句说明 idea 的内容，that 在从句中不充当主语或宾语；the idea that she proposed 中 that 代替 idea 作 proposed 的宾语，是定语从句。区分方法是看从句是否缺少成分。The claim that dreams predict events 的从句主谓宾完整，所以是内容从句。用 claim、belief 或 hypothesis 命名内容，能提醒读者这还不是已证实的事实。</p><p><strong>L19 原创例句：</strong> The belief that every dream has one fixed meaning is difficult to justify.</p><p>认为每个梦都有一个固定含义的信念很难得到充分支持。</p><p><strong>易错：</strong> 不要把 belief 自动译成“事实”；the belief that 只标明某人持有的看法。</p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-019">Lesson 19</a></p><h2 id="过去分词作后置定语" tabindex="-1">过去分词作后置定语 <a class="header-anchor" href="#过去分词作后置定语" aria-label="Permalink to &quot;过去分词作后置定语&quot;">​</a></h2><p>名词 + 过去分词短语通常可展开为被动关系从句：samples collected yesterday 等于 samples that were collected yesterday。过去分词不必总表示过去时间，关键是与名词的被动关系；the methods used today 也可指现在。现在分词通常表达主动或进行关系。写作时要清楚谁执行动作，避免把 substances producing an effect 与 substances produced in a laboratory 混淆。</p><p><strong>L20 原创例句：</strong> The samples collected on Tuesday were analysed separately.</p><p>周二采集的样本被分别分析。</p><p><strong>易错：</strong> 不要把 collected 当成全句唯一谓语而漏掉 were analysed；该短语只限定样本。</p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-020">Lesson 20</a></p><h2 id="it-is-was-that-强调句" tabindex="-1">It is/was…that 强调句 <a class="header-anchor" href="#it-is-was-that-强调句" aria-label="Permalink to &quot;It is/was…that 强调句&quot;">​</a></h2><p>强调句用 It is/was + 被强调部分 + that/who + 其余成分，常强调主语、宾语或状语。It was the lighting that changed the scene. 去掉 It was 与 that 后可还原 The lighting changed the scene。不要把所有 it is…that 都当强调句：It is clear that… 中 it 是形式主语，clear 不能作为原句成分还原。强调时间通常仍用 that，而不是 when。</p><p><strong>L21 原创例句：</strong> It was the actor’s silence that made the final scene so tense.</p><p>正是演员的沉默让最后一幕如此紧张。</p><p><strong>易错：</strong> It was in 1910 when… 若意在强调时间，应使用 that；when 另可引导关系或时间从句。</p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-021">Lesson 21</a></p><h2 id="what-从句作主语与表语" tabindex="-1">what 从句作主语与表语 <a class="header-anchor" href="#what-从句作主语与表语" aria-label="Permalink to &quot;what 从句作主语与表语&quot;">​</a></h2><p>what 从句相当于 the thing(s) that，内部的 what 同时承担从句成分。What matters is how the knowledge is used. 中 what 作 matters 的主语，整个从句作主句主语。that 内容从句中的 that 通常不充当从句成分，因此不可随意互换。what 从句作主语时谓语往往用单数；若语义明确指多个事物，实际一致关系需看整体结构，初学写作宜使用清晰单数表达。</p><p><strong>L22 原创例句：</strong> What matters is whether the new tool solves a real problem.</p><p>重要的是新工具是否解决了一个真实问题。</p><p><strong>易错：</strong> That matters is… 不能替代 What matters is…；what 在从句中还承担 matters 的主语。</p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-022">Lesson 22</a></p><h2 id="现在分词状语与逻辑主语" tabindex="-1">现在分词状语与逻辑主语 <a class="header-anchor" href="#现在分词状语与逻辑主语" aria-label="Permalink to &quot;现在分词状语与逻辑主语&quot;">​</a></h2><p>现在分词短语可表示同时动作、方式或伴随，通常与主句主语共享动作执行者。Gliding above the lake, the bird changed direction. 中 gliding 的执行者是 bird。若写 Gliding above the lake, the wind grew stronger，就错误地让 wind 执行滑翔动作，形成悬垂修饰。分词不独立标明时态，时间关系由主句和语境确定；需要明确不同主语时改用完整从句。</p><p><strong>L23 原创例句：</strong> Gliding above the field, the bird turned towards the hills.</p><p>鸟在田野上方滑翔着，转向了群山。</p><p><strong>易错：</strong> Watching the bird, its wings looked wide 错把 wings 当观察者；可改为 As I watched the bird, its wings looked wide。</p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-023">Lesson 23</a></p><h2 id="否定或限制副词前置倒装" tabindex="-1">否定或限制副词前置倒装 <a class="header-anchor" href="#否定或限制副词前置倒装" aria-label="Permalink to &quot;否定或限制副词前置倒装&quot;">​</a></h2><p>Never、rarely、seldom、not until 等放在句首强调时，主句通常采用助动词在主语之前的部分倒装：Rarely do we agree on every detail。原句没有助动词时根据时态添加 do/does/did，实义动词恢复原形。Not until 引导时间短语或从句时，倒装发生在后面的主句，而不是 until 从句。倒装增加修辞强调，日常说明无需句句使用。</p><p><strong>L24 原创例句：</strong> Rarely do two viewers notice exactly the same details in a painting.</p><p>两位观者很少会注意到一幅画中完全相同的细节。</p><p><strong>易错：</strong> Rarely two viewers notice… 缺倒装；Rarely do two viewers notices… 又错误地给实义动词加 s。</p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-024">Lesson 24</a></p>',50)])])}const w=t(i,[["render",o]]);export{g as __pageData,w as default};
